  use Veltrion\Services\AI\FeatureEngine\DTOs\FeatureDTO; class TraceabilityEngine { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function discoverTraceability(FeatureDTO $feature): array { $featureId = $feature->id; $slug = $feature->slug; $cleanName = strtolower(str_replace('-', '', $slug)); $confirmedFiles = []; $inferredFiles = []; $confirmedTests = []; $inferredTests = []; $appDir = $this->projectRoot . '/app'; if (is_dir($appDir)) { $iterator = new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($appDir)); foreach ($iterator as $file) { if ($file->isFile() && $file->getExtension() === 'php') { $relPath = str_replace($this->projectRoot . '/', '', $file->getPathname()); $content = file_get_contents($file->getPathname()); if (str_contains($content, $featureId)) { $confirmedFiles[] = $relPath; } elseif (str_contains(strtolower($file->getFilename()), strtolower($feature->name)) || str_contains(strtolower($relPath), $cleanName)) { $inferredFiles[] = $relPath; } } } } if (file_exists($this->projectRoot . '/cli')) { $cliContent = file_get_contents($this->projectRoot . '/cli'); if (str_contains($cliContent, $featureId) || str_contains(strtolower($cliContent), strtolower($feature->name))) { $confirmedTests[] = "cli test (Integrated CLI Test Suite)"; } } $securityStatus = 'PENDING'; $securityReportFile = $this->projectRoot . '/storage/reports/securityagent_report.json'; if (file_exists($securityReportFile)) { $secData = json_decode(file_get_contents($securityReportFile), true); $securityStatus = ($secData['summary']['critical'] ?? 0) === 0 ? 'PASS' : 'FAIL'; } $e2eStatus = 'PENDING'; $e2eReportFile = $this->projectRoot . '/storage/reports/e2eagent_report.json'; if (file_exists($e2eReportFile)) { $e2eData = json_decode(file_get_contents($e2eReportFile), true); $e2eStatus = ($e2eData['summary']['high'] ?? 0) === 0 ? 'PASS' : 'FAIL'; } $docsStatus = 'PENDING'; $docsDir = $this->projectRoot . '/docs'; if (is_dir($docsDir)) { $docsStatus = 'PASS'; } return [ 'feature_id' => $featureId, 'name' => $feature->name, 'status' => $feature->status, 'confirmed_code' => array_unique($confirmedFiles), 'inferred_code' => array_unique($inferredFiles), 'confirmed_tests' => array_unique($confirmedTests), 'inferred_tests' => array_unique($inferredTests), 'security_status' => $securityStatus, 'e2e_status' => $e2eStatus, 'documentation_status' => $docsStatus, 'traceability_matrix' => $this->buildMatrix($feature, $confirmedFiles, $inferredFiles, $securityStatus, $e2eStatus) ]; } private function buildMatrix(FeatureDTO $feature, array $confirmedFiles, array $inferredFiles, string $secStatus, string $e2eStatus): array { $matrix = []; $allFiles = array_merge($confirmedFiles, $inferredFiles); $codeSummary = empty($allFiles) ? 'Pending' : implode(', ', array_slice($allFiles, 0, 3)); foreach ($feature->requirements as $r) { $rArr = is_array($r) ? $r : $r->toArray(); $matrix[] = [ 'requirement_id' => $rArr['id'], 'feature_id' => $feature->id, 'code_files' => $codeSummary, 'tests' => 'Integrated CLI Test Suite', 'security' => $secStatus, 'e2e' => $e2eStatus, 'status' => $rArr['status'] ?? 'PLANNED' ]; } return $matrix; } public function generateReport(array $traceData): void { $reportDir = $this->projectRoot . '/storage/reports/traceability'; if (!is_dir($reportDir)) { mkdir($reportDir, 0777, true); } $jsonFile = $reportDir . "/{$traceData['feature_id']}_traceability.json"; file_put_contents($jsonFile, json_encode($traceData, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); $mdFile = $reportDir . "/{$traceData['feature_id']}_traceability.md"; $md = "# Reporte de Trazabilidad: {$traceData['name']} ({$traceData['feature_id']})\n\n" . "- **Estado Feature**: `{$traceData['status']}`\n" . "- **Seguridad (SAST)**: `{$traceData['security_status']}`\n" . "- **End-To-End (E2E)**: `{$traceData['e2e_status']}`\n" . "- **Documentación**: `{$traceData['documentation_status']}`\n\n" . "## Matriz de Trazabilidad de Requisitos (RTM)\n\n" . "| Requisito | Código Confirmado / Inferido | Pruebas | Seguridad | E2E |\n" . "|---|---|---|---|---|\n"; foreach ($traceData['traceability_matrix'] as $row) { $md .= "| `{$row['requirement_id']}` | {$row['code_files']} | {$row['tests']} | `{$row['security']}` | `{$row['e2e']}` |\n"; } file_put_contents($mdFile, $md); } } 